create or replace function public.pantavion_can_send_to_conversation(p_conversation_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select public.pantavion_is_conversation_member(p_conversation_id,p_user_id) and not exists(select 1 from public.conversation_members a join public.conversation_members b on b.conversation_id=a.conversation_id and b.user_id<>a.user_id and b.left_at is null where a.conversation_id=p_conversation_id and a.user_id=p_user_id and a.left_at is null and public.pantavion_has_block_between(a.user_id,b.user_id))$$; create or replace function public.pantavion_can_access_message(p_message_id uuid,p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.messages m where m.id=p_message_id and public.pantavion_is_conversation_member(m.conversation_id,p_user_id))$$; create or replace function public.pantavion_request_relationship(p_addressee_id uuid) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare actor uuid:=auth.uid(); rid uuid; existing public.relationships%rowtype; begin if actor is null then raise exception 'authentication required'; end if; if p_addressee_id is null or p_addressee_id=actor then raise exception 'invalid addressee'; end if; if public.pantavion_has_block_between(actor,p_addressee_id) then raise exception 'relationship blocked'; end if; select * into existing from public.relationships r where least(r.requester_id,r.addressee_id)=least(actor,p_addressee_id) and greatest(r.requester_id,r.addressee_id)=greatest(actor,p_addressee_id) limit 1; if found and existing.status in('pending','accepted') then return existing.id; end if; if found then delete from public.relationships where id=existing.id; end if; insert into public.relationships(requester_id,addressee_id,status) values(actor,p_addressee_id,'pending') returning id into rid; return rid; end$$; create or replace function public.pantavion_respond_relationship(p_relationship_id uuid,p_action text) returns text language plpgsql security definer set search_path=public,pg_temp as $$declare actor uuid:=auth.uid(); rel public.relationships%rowtype; ns text; begin if actor is null then raise exception 'authentication required'; end if; if p_action not in('accept','decline') then raise exception 'invalid action'; end if; select * into rel from public.relationships where id=p_relationship_id for update; if not found or rel.addressee_id<>actor or rel.status<>'pending' then raise exception 'not allowed'; end if; ns:=case when p_action='accept' then 'accepted' else 'declined' end; update public.relationships set status=ns,updated_at=now() where id=p_relationship_id; return ns; end$$; create or replace function public.pantavion_create_direct_conversation(p_other_user_id uuid) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare actor uuid:=auth.uid(); cid uuid; begin if actor is null then raise exception 'authentication required'; end if; if p_other_user_id is null or p_other_user_id=actor then raise exception 'invalid participant'; end if; if public.pantavion_has_block_between(actor,p_other_user_id) then raise exception 'conversation blocked'; end if; if not public.pantavion_are_connections(actor,p_other_user_id) then raise exception 'accepted relationship required'; end if; select c.id into cid from public.conversations c where c.kind='direct' and exists(select 1 from public.conversation_members m where m.conversation_id=c.id and m.user_id=actor and m.left_at is null) and exists(select 1 from public.conversation_members m where m.conversation_id=c.id and m.user_id=p_other_user_id and m.left_at is null) and 2=(select count(*) from public.conversation_members m where m.conversation_id=c.id and m.left_at is null) limit 1; if cid is not null then return cid; end if; insert into public.conversations(kind,created_by) values('direct',actor) returning id into cid; insert into public.conversation_members(conversation_id,user_id,role) values(cid,actor,'owner'),(cid,p_other_user_id,'member'); return cid; end$$; create or replace function public.pantavion_send_message(p_conversation_id uuid,p_body text,p_client_message_id text default null,p_original_language text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$declare actor uuid:=auth.uid(); mid uuid; clean text:=btrim(coalesce(p_body,'')); begin if actor is null then raise exception 'authentication required'; end if; if clean='' or char_length(clean)>10000 then raise exception 'invalid message body'; end if; if not public.pantavion_can_send_to_conversation(p_conversation_id,actor) then raise exception 'not allowed to send'; end if; if p_client_message_id is not null then select id into mid from public.messages where sender_id=actor and client_message_id=p_client_message_id limit 1; if mid is not null then return mid; end if; end if; insert into public.messages(conversation_id,sender_id,client_message_id,body,original_language,message_type) values(p_conversation_id,actor,nullif(p_client_message_id,''),clean,nullif(p_original_language,''),'text') returning id into mid; insert into public.message_receipts(message_id,user_id,state) values(mid,actor,'accepted') on conflict do nothing; return mid; end$$; create or replace function public.pantavion_mark_message_receipt(p_message_id uuid,p_state text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare actor uuid:=auth.uid(); begin if actor is null then raise exception 'authentication required'; end if; if p_state not in('delivered','read') then raise exception 'invalid receipt state'; end if; if not public.pantavion_can_access_message(p_message_id,actor) then raise exception 'message not accessible'; end if; insert into public.message_receipts(message_id,user_id,state) values(p_message_id,actor,p_state) on conflict do nothing; end$$; revoke all on function public.pantavion_can_send_to_conversation(uuid,uuid),public.pantavion_can_access_message(uuid,uuid) from public,anon,authenticated; revoke all on function public.pantavion_request_relationship(uuid),public.pantavion_respond_relationship(uuid,text),public.pantavion_create_direct_conversation(uuid),public.pantavion_send_message(uuid,text,text,text),public.pantavion_mark_message_receipt(uuid,text) from public,anon; grant execute on function public.pantavion_request_relationship(uuid),public.pantavion_respond_relationship(uuid,text),public.pantavion_create_direct_conversation(uuid),public.pantavion_send_message(uuid,text,text,text),public.pantavion_mark_message_receipt(uuid,text) to authenticated;